def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0]); bg=8
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    r0,r1=min(r for r,_ in cells),max(r for r,_ in cells)
    c0,c1=min(c for _,c in cells),max(c for _,c in cells)
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if g[r][c]==bg: g[r][c]=2
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if g[r][c]==bg: g[r][c]=2
    if (r1-r0)%2==0:
        m=(r0+r1)//2
        for c in range(c0,c1+1):
            if g[m][c]==bg: g[m][c]=2
    if (c1-c0)%2==0:
        m=(c0+c1)//2
        for r in range(r0,r1+1):
            if g[r][m]==bg: g[r][m]=2
    return g

